store={}
def run(day, rows):
    store[day]=[r for r in rows if r['day']==day]   # 그날 칸을 덮어쓴다
rows=[{'day':'2026-11-25','n':3},{'day':'2026-11-25','n':4},{'day':'2026-11-26','n':1}]
run('2026-11-25',rows); run('2026-11-25',rows)
print({d:sum(r['n'] for r in v) for d,v in store.items()})
app={'2026-11-25':[]}
for _ in range(2):
    app['2026-11-25'] += [r for r in rows if r['day']=='2026-11-25']
print('append twice', sum(r['n'] for r in app['2026-11-25']))
